<script lang="ts">
import {Component} from 'vue-property-decorator'
import {PortalVueBase} from '@/view/PortalVueBase'
import LanguagePicker from '@/view/LanguagePicker.vue'
import Footer from '@/view/Footer.vue'
import {canonicalOrigin, canonicalUrl, organizationNode, organizationReference, pageMetaInfo, personStub, socialCardPath, websiteId} from '@/model/Seo'
import {brandName} from '@/model/Brand'
import BrandLogo from '@/view/BrandLogo.vue'
import {Locale} from '@/model/content/Locale'
import {musicAppsRootPathFor} from '@/model/MusicApps'

@Component({components: {BrandLogo, Footer, LanguagePicker}})
export default class Gateway extends PortalVueBase {
  brandName = brandName

  get musicAppsPath(): string {
    return musicAppsRootPathFor(Locale.active)
  }

  metaInfo(): any {
    const structuredData = {
      '@context': 'https://schema.org',
      '@graph': [
        {
          '@type': 'WebSite',
          '@id': websiteId(),
          name: brandName,
          url: canonicalOrigin,
          description: this.titles.gatewaySeoDescription,
          inLanguage: Locale.active,
          publisher: organizationReference(),
          hasPart: [
            {
              '@type': 'WebSite',
              name: this.titles.gatewayServicesTitle,
              url: canonicalUrl(this.constants.introductionPath)
            },
            {
              '@type': 'WebSite',
              name: 'Renetik Music Apps',
              url: `${canonicalOrigin}${this.musicAppsPath}`
            }
          ]
        },
        organizationNode(this.model.profile),
        personStub(this.model.profile)
      ]
    }
    return pageMetaInfo(
      this.titles.gatewaySeoTitle,
      this.titles.gatewaySeoDescription,
      this.constants.gatewayPath,
      socialCardPath(this.constants.gatewayPath),
      structuredData,
      brandName
    )
  }
}
</script>
