<template>
  <v-menu bottom left offset-y>
    <template #activator="{on}">
      <v-btn :aria-label="`${titles.languagePickerLabel}: ${activeOption.name}`"
             :title="titles.languagePickerLabel"
             class="language-picker-button"
             flat
             v-on="on">
        <v-icon left>language</v-icon>
        <span>{{ activeOption.shortName }}</span>
        <v-icon right>arrow_drop_down</v-icon>
      </v-btn>
    </template>
    <v-list class="language-menu" dense>
      <v-list-tile :aria-current="option.code === activeLocale ? 'true' : undefined"
                   :key="option.code"
                   @click="select(option.code)"
                   v-for="option in localeOptions">
        <v-list-tile-content>
          <v-list-tile-title :class="{'language-menu__title--active': option.code === activeLocale}">
            {{ option.name }}
          </v-list-tile-title>
        </v-list-tile-content>
        <v-list-tile-action>
          <v-icon color="primary" v-if="option.code === activeLocale">check</v-icon>
        </v-list-tile-action>
      </v-list-tile>
    </v-list>
  </v-menu>
</template>

<style lang="stylus" scoped>
.language-picker-button
  min-width 92px
  height $site-top-bar-height
  margin 0
  padding 0 8px

.language-menu
  min-width 180px

.language-menu__title--active
  color var(--primary-color)

@media all and (max-width: $site-bp-compact-header)
  .language-picker-button
    height $site-top-bar-mobile-height
</style>

<script lang="ts">
import {Component} from 'vue-property-decorator'
import {PortalVueBase} from '@/view/PortalVueBase'
import {Locale, localeOptions, rememberLocale} from '@/model/content/Locale'
import type {Locale as LocaleCode} from '@/model/content/Schema'

@Component
export default class LanguagePicker extends PortalVueBase {
  localeOptions = localeOptions

  get activeLocale() {
    return Locale.active
  }

  get activeOption() {
    return localeOptions.find(option => option.code === this.activeLocale)!
  }

  select(locale: LocaleCode) {
    rememberLocale(locale)
    if (locale === this.activeLocale) return
    const target = Locale.pathFor(locale, this.$route.path)
    window.location.assign(`${target}${this.routeSuffix}`)
  }

  private get routeSuffix() {
    const query = window.location.search || ''
    const hash = window.location.hash || ''
    return `${query}${hash}`
  }
}
</script>
