<template>
  <div class="brand-logo">
    <span class="brand-logo__mark" :style="brandLogoStyle" aria-hidden="true"></span>
    <component :is="titleTag" class="brand-logo__title">{{ brandName }}</component>
  </div>
</template>

<style lang="stylus" scoped>
.brand-logo
  display inline-flex
  align-items center
  line-height 1

.brand-logo__mark
  display block
  flex 0 0 auto
  width 1.5em
  height 1.5em
  background-color currentColor
  mask-position center
  mask-repeat no-repeat
  mask-size contain
  -webkit-mask-position center
  -webkit-mask-repeat no-repeat
  -webkit-mask-size contain

.brand-logo__title
  margin 0
  color inherit
  font inherit
  line-height 1
</style>

<script lang="ts">
import {Component, Prop} from 'vue-property-decorator'
import Vue from 'vue'
import {brandLogoPath, brandName} from '@/model/Brand'

@Component
export default class BrandLogo extends Vue {
  @Prop({default: 'span'}) readonly titleTag!: string

  brandName = brandName

  get brandLogoStyle() {
    const image = `url(${brandLogoPath})`
    return {maskImage: image, WebkitMaskImage: image}
  }
}
</script>
